import time
import sqlite3
from storage import connect


class TokenBucketRateLimiter:
    """Tenant-isolated token bucket rate limiter with fractional accumulation."""

    def __init__(self, db):
        if db is None:
            raise ValueError("db must not be None")
        self.db = db

    def _validate_numeric(self, value, name):
        """Validate that value is a real number (reject bool, None, non-numeric)."""
        if isinstance(value, bool):
            raise ValueError(f"{name} must be a number, got bool")
        if not isinstance(value, (int, float)):
            raise ValueError(f"{name} must be a number, got {type(value).__name__}")
        return float(value)

    def configure(self, key, capacity, refill_rate, now=None):
        """Configure a new token bucket for a given key (tenant).

        Raises ValueError on invalid parameters or if key already exists with different config.
        """
        if not isinstance(key, str) or not key:
            raise ValueError("key must be a non-empty string")

        capacity_f = self._validate_numeric(capacity, "capacity")
        refill_rate_f = self._validate_numeric(refill_rate, "refill_rate")

        if capacity_f <= 0:
            raise ValueError("capacity must be positive")
        if refill_rate_f < 0:
            raise ValueError("refill_rate must be non-negative")

        now_f = time.time() if now is None else self._validate_numeric(now, "now")

        try:
            # Check if key already exists
            row = self.db.execute("SELECT capacity, refill_rate FROM buckets WHERE key=?", (key,)).fetchone()
            if row is not None:
                # Idempotency check: same config is OK, different config raises
                if row[0] != capacity_f or row[1] != refill_rate_f:
                    raise ValueError(f"Key '{key}' already configured with different parameters")
                # Same config: update nothing, just return
                return
            self.db.execute(
                "INSERT INTO buckets (key, capacity, refill_rate, tokens, last_updated) VALUES (?, ?, ?, ?, ?)",
                (key, capacity_f, refill_rate_f, capacity_f, now_f)
            )
            self.db.commit()
        except ValueError:
            raise
        except Exception as e:
            self.db.rollback()
            raise ValueError(f"Failed to configure bucket: {e}") from e

    def consume(self, key, tokens=1, now=None):
        """Attempt to consume tokens from the bucket.

        Returns:
            (True, remaining, 0.0) if consumption succeeded.
            (False, 0.0, wait_time) if consumption failed.
        """
        if not isinstance(key, str) or not key:
            raise ValueError("key must be a non-empty string")

        tokens_f = self._validate_numeric(tokens, "tokens")
        if tokens_f <= 0:
            raise ValueError("tokens must be positive")

        now_f = time.time() if now is None else self._validate_numeric(now, "now")

        try:
            # Atomic transaction: read, compute, write
            row = self.db.execute(
                "SELECT capacity, refill_rate, tokens, last_updated FROM buckets WHERE key=?",
                (key,)
            ).fetchone()

            if row is None:
                # Fail-closed: no bucket configured for this key
                return False, 0.0, 1.0

            capacity, refill_rate, stored_tokens, last_updated = row

            # Clock drift protection: never go backwards
            if now_f < last_updated:
                now_f = last_updated

            # Fractional token accumulation
            elapsed = now_f - last_updated
            new_tokens = stored_tokens + elapsed * refill_rate

            # Cap at capacity
            if new_tokens > capacity:
                new_tokens = capacity

            if new_tokens >= tokens_f:
                # Consumption succeeds
                remaining = new_tokens - tokens_f
                self.db.execute(
                    "UPDATE buckets SET tokens=?, last_updated=? WHERE key=?",
                    (remaining, now_f, key)
                )
                self.db.commit()
                return True, remaining, 0.0
            else:
                # Consumption fails: update last_updated to avoid token loss on next check,
                # but keep tokens at the accumulated amount
                self.db.execute(
                    "UPDATE buckets SET tokens=?, last_updated=? WHERE key=?",
                    (new_tokens, now_f, key)
                )
                self.db.commit()
                # Time until enough tokens are available
                deficit = tokens_f - new_tokens
                if refill_rate > 0:
                    wait_time = deficit / refill_rate
                else:
                    wait_time = float('inf')
                return False, 0.0, wait_time
        except ValueError:
            self.db.rollback()
            raise
        except Exception as e:
            self.db.rollback()
            raise ValueError(f"Failed to consume tokens: {e}") from e
